COURSE = dict(id="nri-tax-residency", level="practitioner", title="NRI residency and tax basics", sec="nri", track="nri-basics", topic="NRI", tag="NRI",
  blurb="Who counts as an NRI, how residential status is decided, what India taxes, and how treaties and returns work.",
  hook="Your passport does not decide your tax status. Your days in India do. Get the status right and most other NRI rules fall into place.",
  fun=["The same person can be an NRI under FEMA and a resident under the Income Tax Act in the same year.", "A tax residency certificate from your country of residence can lower the tax withheld on Indian income."],
  traps=["Assuming NRI status under FEMA and under tax law is the same thing.", "Not filing a return because tax was already deducted.", "Forgetting that your country of residence may also tax Indian income."],
  lessons=[
  dict(title="Who is an NRI", intro="Two laws use the word NRI differently: FEMA for money rules and the Income Tax Act for tax.", concepts=[
    ("NRI under FEMA", "NRI under FEMA is a person of Indian origin or citizenship who lives outside India for work, business, study or another purpose of uncertain duration.", "A software engineer from Pune who has moved to Dubai on a work visa for several years is treated as an NRI for banking and investing rules."),
    ("Residential status for tax", "Residential status for tax is decided each year by counting days spent in India, and it decides whether global income is taxed in India.", "A person who spends fewer days in India than the test requires is treated as a non-resident for that year."),
    ("OCI cardholder", "An OCI cardholder is a foreign citizen of Indian origin who holds a lifelong Overseas Citizen of India card, and is treated like an NRI for many banking and investment rules.", "A Canadian citizen born in India uses an OCI card to open an NRO account."),
    ("RNOR", "RNOR, or resident but not ordinarily resident, is a tax status where mainly income from India, plus some foreign income linked to India, is taxed.", "A person who returns to India after many years abroad may fall in this status for a few years.")],
    client=("“I live in the UAE. Am I an NRI or not?”", "A client unsure which rule applies."), talk="“There are two tests. One is for banking and investing under FEMA. The other is for tax and depends on the days you spent in India this year. Let us check both before we decide anything.”", remember=["FEMA and tax law use different tests.", "Days in India drive tax status.", "Status can change every year."]),
  dict(title="What India taxes", intro="India taxes people differently depending on status. A non-resident is taxed mainly on India-linked income.", concepts=[
    ("Global income", "Global income is income earned anywhere in the world, and residents are taxed on it in India.", "A resident who earns rent from a flat abroad reports it in India."),
    ("India-sourced income", "India-sourced income is income earned or received in India, such as rent, capital gains on Indian assets and NRO interest, and it is taxable for non-residents.", "An NRI who sells Indian shares pays Indian tax on the gain."),
    ("NRE interest exemption", "NRE interest exemption means interest on an NRE account is generally free of Indian tax while the holder remains a non-resident.", "An NRI earns interest on an NRE fixed deposit and pays no Indian tax on it."),
    ("TDS on NRI income", "TDS on NRI income is tax deducted at source on payments to NRIs, often at higher rates than for residents.", "A buyer deducts tax at source when paying an NRI for a flat.")],
    client=("“Why was so much tax cut when I sold my shares?”", "An NRI surprised by deducted tax."), talk="“Payments to non-residents often carry tax at source. If the deduction is more than your actual liability, you can claim the excess back by filing a return.”", remember=["Non-residents pay tax on India income.", "NRE interest is generally exempt.", "TDS can be higher for NRIs."]),
  dict(title="Treaties and double tax", intro="Income can be taxed in two countries. Treaties and credits reduce the double bite.", concepts=[
    ("DTAA", "DTAA is a double taxation avoidance agreement between two countries that decides who may tax which income and at what rate.", "An NRI in a treaty country claims a lower tax rate on Indian interest."),
    ("Tax residency certificate", "A tax residency certificate is a document from the tax authority of your country of residence proving you live there for tax, often needed to claim treaty benefits.", "An NRI shares this certificate with an Indian bank to get treaty rates applied."),
    ("Foreign tax credit", "Foreign tax credit lets you reduce tax in one country by the tax already paid on the same income in another.", "An NRI pays tax in India on rent and claims credit for it when filing in the country of residence."),
    ("Tie-breaker rule", "A tie-breaker rule is a treaty test, such as permanent home or centre of vital interests, that decides which country treats you as resident when both claim you.", "A person with homes in two countries uses this test to settle where they are resident.")],
    client=("“I pay tax in both countries. Is that fair?”", "A client worried about double tax."), talk="“Usually you do not pay twice on the same income. Treaties and foreign tax credit exist for this. Keep the tax paperwork from both countries.”", remember=["Treaties divide taxing rights.", "A residency certificate unlocks benefits.", "Keep proof of tax paid."]),
  dict(title="Returns and refunds", intro="Filing a return is how an NRI claims refunds and keeps a clean record.", concepts=[
    ("Return filing", "Return filing is submitting your income tax return, which an NRI needs to do when Indian income crosses the exemption limit or when a refund is due.", "An NRI files a return to claim back excess tax deducted on a sale."),
    ("PAN", "PAN is the permanent account number needed for most financial transactions and tax filing in India.", "An NRI gets a ten-character tax number from the income tax department before investing in mutual funds."),
    ("TDS refund", "A TDS refund is the return of tax deducted at source that exceeds your actual tax liability, claimed through a return.", "A higher deduction on a property sale is refunded after the return is processed."),
    ("Lower deduction certificate", "A lower deduction certificate is an order from the tax officer allowing payers to deduct less tax at source, applied for in advance.", "An NRI selling a flat applies for this certificate so the buyer deducts less.")],
    client=("“Tax was already cut. Do I still need to file?”", "A client who thinks deduction ends the duty."), talk="“Not always, but if too much was cut you can only get it back by filing. Filing also keeps your record clean for future sales and loans.”", remember=["Filing can bring a refund.", "A PAN is essential.", "Lower deduction needs advance application."]),
  dict(title="Staying compliant", intro="Good records and honest declarations prevent most NRI trouble.", concepts=[
    ("Self-certification", "Self-certification is a form in which you declare your countries of tax residence to a bank or fund house.", "An NRI fills the form when opening an account."),
    ("Foreign income reporting", "Foreign income reporting means declaring income earned in India to the tax authority of the country where you live, as that country may tax worldwide income.", "An NRI in the United Kingdom reports Indian rent in the UK return."),
    ("Record keeping", "Record keeping means saving statements, tax forms and proofs of remittance for every year.", "An NRI keeps bank certificates that show tax deducted."),
    ("Professional advice", "Professional advice means asking a qualified tax adviser when rules in two countries interact, because the answer depends on facts.", "An NRI meets a chartered accountant before selling an inherited property.")],
    client=("“Do I have to tell my UK tax office about Indian income?”", "A client unsure of the other country’s rules."), talk="“Many countries tax their residents on worldwide income, so yes, you usually need to report it there. Rules differ, so confirm with an adviser in that country.”", remember=["Declare residence truthfully.", "Report India income abroad.", "Keep every proof."]),
  ])
